param([string]$ProjectRoot=(Join-Path $PSScriptRoot '..'),[string]$BuildRoot='')
$ErrorActionPreference='Stop';$ProjectRoot=[IO.Path]::GetFullPath($ProjectRoot);if(!$BuildRoot){$BuildRoot=Join-Path $ProjectRoot 'out/staging'};$BuildRoot=[IO.Path]::GetFullPath($BuildRoot)
Add-Type -Path (Join-Path $PSScriptRoot 'PrivateDesktop.cs');Add-Type -Path (Join-Path $PSScriptRoot 'NativeChatTest.cs')
$root=Join-Path $ProjectRoot ('artifacts/rhythm-desktop-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $root|Out-Null;Set-Content "$root/.synthetic-world-journal-test" 'Synthetic data only.'
$desktop=$null;$service=$null;$provider=$null;$checks=0;$env:HIBERNATION_SESSION_KEY='rhythm-fixture-session';$env:HIBERNATION_RHYTHM_KEY='synthetic-only';$env:TEMP="$BuildRoot/tmp";$env:TMP=$env:TEMP
function Check($Value,$Name){if(!$Value){throw "CHECK FAILED: $Name"};$script:checks++;Write-Output "PASS $Name"}
function Wait-For([scriptblock]$Probe,$Name,[int]$Seconds=25){$end=[DateTime]::UtcNow.AddSeconds($Seconds);while([DateTime]::UtcNow-lt$end){if(& $Probe){return};Start-Sleep -Milliseconds 35};try{Api '/api/capabilities'|ConvertTo-Json -Depth 35|Set-Content "$root/timeout.json"}catch{};throw "TIMEOUT $Name"}
function Api($Path,$Data=$null){$a=@{Uri=$script:origin+$Path;Headers=@{Authorization='Bearer rhythm-fixture-session'};TimeoutSec=12};if($null-ne$Data){$a.Method='Post';$a.ContentType='application/json';$a.Body=[Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 35 -Compress))};Invoke-RestMethod @a}
function Current($Id){(Api '/api/capabilities').plugins.Where({$_.id-eq$Id})[0].current}
function Rhythm{Current 'rhythm'}
function Widget{Current 'widget'}
function Plugin($Name,$Arguments){$null=Api '/api/plugin/test' @{tool=$Name;args=$Arguments};Wait-For {$script:result=Api '/api/plugin/result';$script:result.state-in@('succeeded','failed')} $Name;return $script:result.result}
function Inspect{$value=& "$BuildRoot/Hibernation_WorldArchiveFixture.exe" inspect $root;if($LASTEXITCODE-ne0){throw 'archive fixture failed'};$value|ConvertFrom-Json}
function Checkpoint{$null=Api '/api/surfaces/show' @{id='widget'};Inspect}
function Rest($Seconds=15){$value=Plugin 'rhythm.rest' @{seconds=$Seconds};Check ($value.ok-and$value.result.accepted-and!$value.result.completed) 'rest is initially an intent'|Out-Host;Wait-For {(Rhythm).phase-eq'active'} 'confirmed rest';return (Rhythm).token}
function Start-Backend{Remove-Item "$root/ready.json" -ErrorAction SilentlyContinue;$script:desktop=[PrivateDesktop]::new("$BuildRoot/hibernation-agent.exe","$root/config.json","$root/ready.json",$ProjectRoot);$script:service=$desktop.Child;Wait-For {if($service.HasExited){throw 'fixture exited'};Test-Path "$root/ready.json"} 'backend';$script:origin='http://127.0.0.1:'+((Get-Content "$root/ready.json" -Raw|ConvertFrom-Json).port);Wait-For {(Rhythm).desktop} 'rhythm'}
function Stop-Backend{$null=Api '/api/shutdown' @{};Check ($service.WaitForExit(10000)-and$service.ExitCode-eq0) 'rhythm backend exits cleanly';$desktop.Dispose();$script:desktop=$null}
function Plan($Items){@{nonce=[Guid]::NewGuid().ToString('N');responses=$Items}|ConvertTo-Json -Depth 40|Set-Content "$root/provider/plan.json" -Encoding utf8}
function Reply($Text){@{version=1;kind='reply';text=$Text;calls=@()}}
function Calls($Items){@{version=1;kind='call';text=$null;calls=$Items}}
try{
 $provider=Start-Process "$BuildRoot/Hibernation_TestProvider.exe" -ArgumentList ('"'+$root+'/provider"') -WindowStyle Hidden -PassThru -RedirectStandardOutput "$root/provider.log" -RedirectStandardError "$root/provider-error.log";Wait-For {Test-Path "$root/provider/port"} 'provider';$fixture='http://127.0.0.1:'+(Get-Content "$root/provider/port")
 $cfg=Get-Content "$ProjectRoot/config/example.json" -Raw|ConvertFrom-Json -AsHashtable;$cfg.dataRoot="$root/data";$cfg.characterRoot="$ProjectRoot/character";$cfg.uiRoot="$ProjectRoot/ui";$cfg.pluginRoot="$BuildRoot/plugins";$cfg.solitudeIntervalMs=604800000;$cfg.idleBeforeSolitudeMs=86400000;$cfg.plugins=@{widget=@{enabled=$true;roam=$false};rhythm=@{enabled=$true;automaticRest=$false};habitat=@{enabled=$true;autoSpawn=$false;autoInteract=$false;wakeOnAction=$false}};$cfg.profiles+=@{id='fixture';label='Rhythm fixture';enabled=$true;protocol='chat-completions';origin=$fixture;basePath='/v1';model='fixture-model';credentialEnvironment='HIBERNATION_RHYTHM_KEY';timeoutMs=10000;maxOutputTokens=2048};$cfg|ConvertTo-Json -Depth 35|Set-Content "$root/config.json" -Encoding utf8
 Start-Backend;Check (@((Api '/api/capabilities').tools|Where-Object {$_.tool-like'rhythm.*'}).Count-eq3) 'rest abilities are discoverable';$before=Checkpoint;$token=Rest;Check ((Widget).state-eq'resting') 'active rest requires the actual widget pose';$started=Inspect;Check ($started.continuous.desired_activity-eq'resting'-and$started.rest_experiences-eq1) 'confirmed rest updates continuous-state target with provenance'
 $food=Plugin 'habitat.place' @{kind='berry'};$attempt=Plugin 'habitat.act' @{id=$food.result.objects[0].id;action='eat'};Check (!$attempt.ok-and$attempt.error.code-eq'world_character_resting') 'autonomous food cannot pull a resting character away';$null=Api '/api/control' @{paused=$true};$frozen=Rhythm;Start-Sleep -Milliseconds 700;Check ((Rhythm).elapsed-eq$frozen.elapsed-and(Rhythm).clock-eq$frozen.clock) 'pause freezes the interval rather than counting wall time';$null=Api '/api/control' @{paused=$false}
 Wait-For {(Rhythm).phase-eq'idle'} 'actual rest finishes' 25;$after=Checkpoint;Check ($after.rest_elapsed-ge14.99-and$after.rest_experiences-eq2) 'completed duration produces one start and one completed experience';Check ($after.continuous.desired_activity-eq'idle'-and$after.continuous.energy-gt$before.continuous.energy-and$after.continuous.energy-$before.continuous.energy-lt.02) 'rest affects energy gradually and releases the activity target';Check ((Invoke-RestMethod ($fixture+'/fixture/health')).calls-eq0-and(Api '/api/chat').messages.Count-eq0) 'quiet rest makes no model calls or chat messages'
 $token=Rest;Wait-For {(Rhythm).elapsed-ge1.2} 'short real rest';$widget=$desktop.Find('HibernationDinosaurOverlay');Check ($widget-ne[IntPtr]::Zero) 'pointer test targets only its private widget';[ChatWindowTest]::UseWindowCoordinates($widget);$screen=New-Object ChatWindowTest+Rect;$null=[ChatWindowTest]::GetClientRect($widget,[ref]$screen);$position=Widget;$x=[int]($position.x*($screen.right-112)+56);$y=[int]($position.y*($screen.bottom-112)+56);$timer=[Diagnostics.Stopwatch]::StartNew();$null=[ChatWindowTest]::Send($widget,0x201,0,($y-shl16)-bor$x);$null=[ChatWindowTest]::Send($widget,0x200,1,($y-shl16)-bor($x+24));$null=[ChatWindowTest]::Send($widget,0x202,0,($y-shl16)-bor($x+24));Wait-For {(Rhythm).phase-eq'idle'} 'drag interruption';Check ($timer.ElapsedMilliseconds-lt500-and(Widget).state-ne'resting') 'drag promptly interrupts rest without delayed speech'
 $null=Api '/api/model' @{id='fixture'};Plan @(@{response=(Calls @(@{id='rest';tool='rhythm.rest';args=@{seconds=15}}))},@{response=(Calls @(@{id='false-memory';tool='memory.remember';args=@{kind='outer';text='尚未开始就声称已经休息完。';source_ids=@('${last_source_id}')}}))},@{response=(Reply '先歇一会儿。');delay_ms=700});$null=Api '/api/message' @{request_id=[Guid]::NewGuid().ToString('N');text='可以歇一会儿。'};Wait-For {(Invoke-RestMethod ($fixture+'/fixture/health')).calls-ge2} 'rest intent during turn';Check ((Rhythm).phase-eq'queued'-and(Api '/api/chat').busy) 'same-turn intent waits for dialogue and speech';Wait-For {!(Api '/api/chat').busy} 'turn';$capture=Get-Content "$root/provider/last-request.json" -Raw|ConvertFrom-Json -Depth 60;$feedback=($capture.messages[-1].content|ConvertFrom-Json -Depth 40).tool_results;Check (!$feedback[0].ok-and$feedback[0].error.code-eq'memory_category_requires_experience') 'rest intent alone cannot authenticate completed-rest memory';Wait-For {(Rhythm).phase-eq'active'} 'deferred rest begins after reply'
 Plan @(@{response=(Reply '嗯，我听着。')});$timer.Restart();$null=Api '/api/message' @{request_id=[Guid]::NewGuid().ToString('N');text='先听这一句。'};Wait-For {(Rhythm).phase-eq'idle'} 'new input ends rest';Check ($timer.ElapsedMilliseconds-lt500) 'new conversation ends rest without waiting for a model reply';Wait-For {!(Api '/api/chat').busy} 'reply';Wait-For {(Widget).state-eq'idle'} 'bubble clears'
 $token=Rest;Wait-For {(Rhythm).elapsed-ge1.2} 'rest before restart';$saved=Rhythm;$null=Checkpoint;Stop-Backend;Start-Backend;Wait-For {(Rhythm).phase-eq'idle'-and(Inspect).continuous.desired_activity-eq'idle'} 'restart ends the previous interval';$reopened=Inspect;$end=@($reopened.rest_results|Where-Object {$_.token-eq$token-and$_.kind-eq'rhythm.rest_interrupted'})[0];Check ($end.reason-eq'application_restarted'-and$end.elapsed-le$saved.elapsed+1) 'restart retains actual elapsed time and invents no offline rest'
 $token=Rest;$settings=(Api '/api/dashboard').settings;$settings.plugins.rhythm.enabled=$false;$null=Api '/api/settings' @{settings=$settings};Wait-For {(Widget).state-ne'resting'} 'unload releases rest pose';$count=(Inspect).rest_experiences;Check ((Inspect).continuous.desired_activity-eq'idle') 'unloading releases the continuous activity';$settings=(Api '/api/dashboard').settings;$settings.plugins.rhythm.enabled=$true;$null=Api '/api/settings' @{settings=$settings};Wait-For {(Rhythm).phase-eq'idle'} 're-enable stays idle';Check ((Inspect).rest_experiences-eq$count) 'plugin reload does not duplicate the previous interruption';Stop-Backend
 @{completed=$true;checks=$checks;root=$root;timestamp=[DateTime]::UtcNow.ToString('O')}|ConvertTo-Json|Set-Content "$root/acceptance.json";Write-Output "Rhythm desktop passed: $checks checks. Evidence: $root"
}finally{if($service){$service.Refresh();if(!$service.HasExited){try{$null=Api '/api/shutdown' @{};$service.WaitForExit(5000)|Out-Null}catch{};$service.Refresh();if(!$service.HasExited){Stop-Process -Id $service.Id}}};if($desktop){$desktop.Dispose()};if($provider){$provider.Refresh();if(!$provider.HasExited){Stop-Process -Id $provider.Id}}}
